INSERT INTO feature VALUES('without-k','identity','The without-K discipline','identity-types','implemented','notable',NULL,'Axiom K is refused by name, so identifications of identifications stay proof-relevant; a theory states a collapsing law of its own sort only as an obligation its models prove, admitted by no host, and no rule matches a path by a bare variable.','core-checker','corpus/pathological/identity/k-derivation.gandr corpus/model/identity/circle-apart.gandr corpus/model/modules/law-collapsed.gandr corpus/pathological/modules/law-collapsed.gandr','corpus/model/identity/circle-apart.gandr',NULL);
